INSERT INTO `_tbsp_guard`VALUES(COALESCE(@tbsp_ok,0));
INSERT INTO `reward_sets`(`reward_set_id`,`title`,`enabled`)SELECT e.`reward_set_id`,e.`title`,e.`enabled` FROM `_tbsp_reward_sets` e WHERE @tbsp_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_sets` a WHERE a.`reward_set_id`<=>e.`reward_set_id`);
INSERT INTO `reward_sources`(`source_type`,`source_id`,`reward_set_id`,`enabled`)SELECT e.`source_type`,e.`source_id`,e.`reward_set_id`,e.`enabled` FROM `_tbsp_reward_sources` e WHERE @tbsp_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_sources` a WHERE a.`source_type`<=>e.`source_type` AND a.`source_id`<=>e.`source_id`);
INSERT INTO `reward_options`(`reward_set_id`,`option_id`,`sequence`,`label`,`common_to_all`,`flags`,`enabled`,`class_mask`)SELECT e.`reward_set_id`,e.`option_id`,e.`sequence`,e.`label`,e.`common_to_all`,e.`flags`,e.`enabled`,e.`class_mask` FROM `_tbsp_reward_options` e WHERE @tbsp_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_options` a WHERE a.`reward_set_id`<=>e.`reward_set_id` AND a.`option_id`<=>e.`option_id`);
INSERT INTO `rewards`(`reward_id`,`reward_type`,`reward_data_id`,`amount`,`description`,`enabled`)SELECT e.`reward_id`,e.`reward_type`,e.`reward_data_id`,e.`amount`,e.`description`,e.`enabled` FROM `_tbsp_rewards` e WHERE @tbsp_ok=1 AND NOT EXISTS(SELECT 1 FROM `rewards` a WHERE a.`reward_id`<=>e.`reward_id`);
INSERT INTO `reward_option_entries`(`reward_set_id`,`option_id`,`sequence`,`reward_id`)SELECT e.`reward_set_id`,e.`option_id`,e.`sequence`,e.`reward_id` FROM `_tbsp_reward_option_entries` e WHERE @tbsp_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_option_entries` a WHERE a.`reward_set_id`<=>e.`reward_set_id` AND a.`option_id`<=>e.`option_id` AND a.`sequence`<=>e.`sequence`);
INSERT INTO `achievement_criteria`(`achievement_id`,`component_type`,`component_sequence`,`component_id`,`event_type`,`progress_mode`,`behavior`,`target_id`,`target_id2`,`target_value`,`required_count`,`enabled`)SELECT e.`achievement_id`,e.`component_type`,e.`component_sequence`,e.`component_id`,e.`event_type`,e.`progress_mode`,e.`behavior`,e.`target_id`,e.`target_id2`,e.`target_value`,e.`required_count`,e.`enabled` FROM `_tbsp_achievement_criteria` e WHERE @tbsp_ok=1 AND NOT EXISTS(SELECT 1 FROM `achievement_criteria` a WHERE a.`achievement_id`<=>e.`achievement_id` AND a.`component_type`<=>e.`component_type` AND a.`component_id`<=>e.`component_id`);
